/// Convert float to hex representation (%a/%A format)
fn float_to_hex(val: f64, uppercase: bool) -> String {
    if val.is_nan() {
        return if uppercase { "NAN" } else { "nan" }.to_string();
    }
    if val.is_infinite() {
        return if val > 0.0 {
            if uppercase {
                "INF"
            } else {
                "inf"
            }
        } else {
            if uppercase {
                "-INF"
            } else {
                "-inf"
            }
        }
        .to_string();
    }
    if val == 0.0 {
        let sign = if val.is_sign_negative() { "-" } else { "" };
        return if uppercase {
            format!("{}0X0P+0", sign)
        } else {
            format!("{}0x0p+0", sign)
        };
    }

    let sign = if val < 0.0 { "-" } else { "" };
    let abs_val = val.abs();
    let bits = abs_val.to_bits();
    let exponent = ((bits >> 52) & 0x7ff) as i32 - 1023;
    let mantissa = bits & 0xfffffffffffff;

    let hex_mantissa = format!("{:013x}", mantissa);
    let hex_mantissa = hex_mantissa.trim_end_matches('0');
    let hex_mantissa = if hex_mantissa.is_empty() {
        "0"
    } else {
        hex_mantissa
    };

    if uppercase {
        format!("{}0X1.{}P{:+}", sign, hex_mantissa.to_uppercase(), exponent)
    } else {
        format!("{}0x1.{}p{:+}", sign, hex_mantissa, exponent)
    }
}

/// Quote a string for shell output (like zsh's set output)
fn shell_quote(s: &str) -> String {
    if s.is_empty() {
        return "''".to_string();
    }
    // Check if quoting is needed
    let needs_quotes = s.chars().any(|c| {
        matches!(
            c,
            ' ' | '\t'
                | '\n'
                | '\''
                | '"'
                | '\\'
                | '$'
                | '`'
                | '!'
                | '*'
                | '?'
                | '['
                | ']'
                | '{'
                | '}'
                | '('
                | ')'
                | '<'
                | '>'
                | '|'
                | '&'
                | ';'
                | '#'
                | '~'
        )
    });
    if !needs_quotes {
        return s.to_string();
    }
    // Use single quotes, escaping single quotes as '\''
    format!("'{}'", s.replace('\'', "'\\''"))
}

/// Quote a value for typeset -p output (re-executable code)
/// Uses single quoting only when the value contains special characters
/// Tokenise a string per zsh's `${(z)var}` semantics: whitespace
/// separates words; shell metacharacters (`;`, `&`, `|`, `(`, `)`,
/// `<`, `>`) emit as their own tokens; single/double quoted regions
/// stay together (with outer quotes stripped). Matches zsh closely
/// enough for the common "split a command line into tokens" use.
fn zsh_split_z(s: &str) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();
    let mut cur = String::new();
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0;
    let flush = |out: &mut Vec<String>, cur: &mut String| {
        if !cur.is_empty() {
            out.push(std::mem::take(cur));
        }
    };
    while i < chars.len() {
        let c = chars[i];
        match c {
            ' ' | '\t' | '\n' => {
                flush(&mut out, &mut cur);
                i += 1;
            }
            ';' | '&' | '|' | '<' | '>' | '(' | ')' => {
                flush(&mut out, &mut cur);
                // Combine repeated metas: `&&`, `||`, `;;`, `>>`, `<<`.
                let mut tok = String::new();
                tok.push(c);
                while i + 1 < chars.len()
                    && chars[i + 1] == c
                    && matches!(c, '&' | '|' | ';' | '<' | '>')
                {
                    tok.push(c);
                    i += 1;
                }
                out.push(tok);
                i += 1;
            }
            '\'' => {
                // Single-quoted: take until matching quote, no expansion.
                i += 1;
                while i < chars.len() && chars[i] != '\'' {
                    cur.push(chars[i]);
                    i += 1;
                }
                if i < chars.len() {
                    i += 1; // skip closing '
                }
            }
            '"' => {
                // Double-quoted: take until matching quote, honor `\"`.
                i += 1;
                while i < chars.len() && chars[i] != '"' {
                    if chars[i] == '\\' && i + 1 < chars.len() {
                        i += 1;
                        cur.push(chars[i]);
                        i += 1;
                        continue;
                    }
                    cur.push(chars[i]);
                    i += 1;
                }
                if i < chars.len() {
                    i += 1; // skip closing "
                }
            }
            '\\' if i + 1 < chars.len() => {
                cur.push(chars[i + 1]);
                i += 2;
            }
            _ => {
                cur.push(c);
                i += 1;
            }
        }
    }
    flush(&mut out, &mut cur);
    out
}

/// Slice an array per zsh `${arr:offset[:length]}` semantics: the
/// offset is 0-based "skip N elements" (so `${arr:1:2}` returns
/// elements at indices 1,2). Negative offset counts from the end.
/// `length < 0` means "to the end".
fn slice_array_zero_based(arr: &[String], offset: i64, length: i64) -> Vec<String> {
    let n = arr.len() as i64;
    if n == 0 {
        return Vec::new();
    }
    let start = if offset < 0 {
        (n + offset).max(0) as usize
    } else {
        (offset as usize).min(arr.len())
    };
    let take = if length < 0 {
        arr.len().saturating_sub(start)
    } else {
        (length as usize).min(arr.len().saturating_sub(start))
    };
    arr.iter().skip(start).take(take).cloned().collect()
}

/// Same shape but for positional params (`@`/`*`). zsh treats
/// position 0 as `$0` (the script/shell name). For `${@:0}` it
/// includes `$0`; for `${@:1}` it skips `$0` and starts at `$1`.
/// Internally `positional_params[0]` is `$1`, so we prepend `$0`
/// then slice 0-based.
fn slice_positionals(exec: &ShellExecutor, offset: i64, length: i64) -> Vec<String> {
    let mut all: Vec<String> = Vec::with_capacity(exec.positional_params.len() + 1);
    all.push(
        exec.variables
            .get("0")
            .cloned()
            .unwrap_or_else(|| std::env::args().next().unwrap_or_default()),
    );
    for p in &exec.positional_params {
        all.push(p.clone());
    }
    slice_array_zero_based(&all, offset, length)
}

/// Normalise a path lexically: collapse `.` and `..` components without
/// touching the filesystem. Used by `cd -L` (default) so symlinks are
/// preserved in `$PWD` (matches zsh's logical-pwd behaviour).
fn normalize_logical(path: &std::path::Path) -> std::path::PathBuf {
    use std::path::Component;
    let mut out = std::path::PathBuf::new();
    for comp in path.components() {
        match comp {
            Component::Prefix(_) | Component::RootDir => out.push(comp.as_os_str()),
            Component::CurDir => {}
            Component::ParentDir => {
                // Pop one component if we have any non-root piece to drop.
                let popped = out.pop();
                if !popped {
                    out.push("..");
                }
            }
            Component::Normal(c) => out.push(c),
        }
    }
    if out.as_os_str().is_empty() {
        out.push(".");
    }
    out
}

fn shell_quote_value(s: &str) -> String {
    if s.is_empty() {
        return "''".to_string();
    }
    let needs_quotes = s.chars().any(|c| {
        matches!(
            c,
            ' ' | '\t'
                | '\n'
                | '\''
                | '"'
                | '\\'
                | '$'
                | '`'
                | '!'
                | '*'
                | '?'
                | '['
                | ']'
                | '{'
                | '}'
                | '('
                | ')'
                | '<'
                | '>'
                | '|'
                | '&'
                | ';'
                | '#'
                | '~'
                | '^'
        )
    });
    if !needs_quotes {
        return s.to_string();
    }
    format!("'{}'", s.replace('\'', "'\\''"))
}

