    fn print_options_table(&self) {
        let mut opts: Vec<_> = Self::all_zsh_options().to_vec();
        opts.sort();
        let defaults_on = Self::default_on_options();
        for &opt in &opts {
            let enabled = self.options.get(opt).copied().unwrap_or(false);
            let is_default_on = defaults_on.contains(&opt);
            // zsh format: for default-ON options, show "noOPTION off" when on, "noOPTION on" when off
            // for default-OFF options, show "OPTION off" when off, "OPTION on" when on
            let (display_name, display_state) = if is_default_on {
                (format!("no{}", opt), if enabled { "off" } else { "on" })
            } else {
                (opt.to_string(), if enabled { "on" } else { "off" })
            };
            println!("{:<22}{}", display_name, display_state);
        }
    }

    fn print_options_reentrant(&self) {
        let mut opts: Vec<_> = Self::all_zsh_options().to_vec();
        opts.sort();
        let defaults_on = Self::default_on_options();
        for &opt in &opts {
            let enabled = self.options.get(opt).copied().unwrap_or(false);
            let is_default_on = defaults_on.contains(&opt);
            // zsh format: use noOPTION for default-on options
            let (display_name, use_minus) = if is_default_on {
                (format!("no{}", opt), !enabled)
            } else {
                (opt.to_string(), enabled)
            };
            if use_minus {
                println!("set -o {}", display_name);
            } else {
                println!("set +o {}", display_name);
            }
        }
    }

    /// caller - display call stack (bash)
    /// caller [N] — bash builtin returning the location of the
    /// current frame N. With no arg or N=0: 'LINE FUNC' (or just
    /// 'LINE main' at top level). With N>0: 'LINE FUNC FILE' for
    /// frame N. Direct port of bash's bin_caller in builtins.def.
    /// Reads from the existing $funcstack array we now maintain
    /// (exec.rs:7828-7835).
    fn builtin_caller(&self, args: &[String]) -> i32 {
        let depth: usize = args.first().and_then(|s| s.parse().ok()).unwrap_or(0);
        let stack = self.arrays.get("funcstack").cloned().unwrap_or_default();
        // funcstack[0] is the current (innermost) frame — caller 0
        // refers to the immediate caller per bash semantics, which
        // is funcstack[0] for us. With no args, just LINE FUNC; we
        // don't track per-frame line numbers yet so emit `0` as
        // line number until the VM pipes that through.
        if depth == 0 {
            let func = stack.first().cloned().unwrap_or_else(|| "main".to_string());
            println!("0 {}", func);
            0
        } else if depth < stack.len() {
            let func = stack[depth].clone();
            // 'main' synonyms shouldn't carry a file. For others,
            // surface the source file from find_function_file when
            // available — same path used by $functions_source.
            let file = self
                .find_function_file(&func)
                .map(|p| p.to_string_lossy().into_owned())
                .unwrap_or_else(|| "main".to_string());
            println!("0 {} {}", func, file);
            0
        } else {
            // Bash returns 1 (no frame at that depth) silently.
            1
        }
    }

    /// doctor - diagnostic report of shell health, caches, and performance
    fn builtin_doctor(&self, _args: &[String]) -> i32 {
        let green = |s: &str| format!("\x1b[32m{}\x1b[0m", s);
        let red = |s: &str| format!("\x1b[31m{}\x1b[0m", s);
        let yellow = |s: &str| format!("\x1b[33m{}\x1b[0m", s);
        let bold = |s: &str| format!("\x1b[1m{}\x1b[0m", s);
        let dim = |s: &str| format!("\x1b[2m{}\x1b[0m", s);

        println!("{}", bold("zshrs doctor"));
        println!("{}", dim(&"=".repeat(60)));
        println!();

        // --- Environment ---
        println!("{}", bold("Environment"));
        println!("  version:    zshrs {}", env!("CARGO_PKG_VERSION"));
        println!("  pid:        {}", std::process::id());
        let cwd = env::current_dir()
            .map(|p| p.to_string_lossy().to_string())
            .unwrap_or_else(|_| "?".to_string());
        println!("  cwd:        {}", cwd);
        println!(
            "  shell:      {}",
            env::var("SHELL").unwrap_or_else(|_| "?".to_string())
        );
        println!("  pool size:  {}", self.worker_pool.size());
        println!(
            "  pool done:  {} tasks completed",
            self.worker_pool.completed()
        );
        println!("  pool queue: {} pending", self.worker_pool.queue_depth());
        println!();

        // --- Config ---
        println!("{}", bold("Config"));
        let config_path = crate::config::config_path();
        if config_path.exists() {
            println!("  {}  {}", green("*"), config_path.display());
        } else {
            println!(
                "  {}  {} {}",
                dim("-"),
                config_path.display(),
                dim("(using defaults)")
            );
        }
        println!();

        // --- PATH ---
        println!("{}", bold("PATH"));
        let path_var = env::var("PATH").unwrap_or_default();
        let path_dirs: Vec<&str> = path_var.split(':').filter(|s| !s.is_empty()).collect();
        let path_ok = path_dirs
            .iter()
            .filter(|d| std::path::Path::new(d).is_dir())
            .count();
        let path_missing = path_dirs.len() - path_ok;
        println!(
            "  directories: {} total, {} {}, {} {}",
            path_dirs.len(),
            path_ok,
            green("valid"),
            path_missing,
            if path_missing > 0 {
                red("missing")
            } else {
                green("missing")
            },
        );
        println!("  hash table:  {} entries", self.command_hash.len());
        println!();

        // --- FPATH ---
        println!("{}", bold("FPATH"));
        println!("  directories: {}", self.fpath.len());
        let fpath_ok = self.fpath.iter().filter(|d| d.is_dir()).count();
        let fpath_missing = self.fpath.len() - fpath_ok;
        if fpath_missing > 0 {
            println!("  {} {} missing fpath directories", red("!"), fpath_missing);
        }
        println!("  functions:   {} loaded", self.function_names().len());
        println!("  autoload:    {} pending", self.autoload_pending.len());
        println!();

        // --- SQLite Caches ---
        println!("{}", bold("SQLite Caches"));
        if let Some(ref engine) = self.history {
            let count = engine.count().unwrap_or(0);
            println!("  history:     {} entries  {}", count, green("OK"));
        } else {
            println!("  history:     {}", yellow("not initialized"));
        }

        if let Some(ref cache) = self.compsys_cache {
            let count = compsys::cache_entry_count(cache);
            println!("  compsys:     {} completions  {}", count, green("OK"));

            // Check bytecode blob coverage
            if let Ok(missing) = cache.get_autoloads_missing_bytecode() {
                if missing.is_empty() {
                    println!(
                        "  bytecode cache:   {}",
                        green("all functions compiled to bytecode")
                    );
                } else {
                    println!(
                        "  bytecode cache:   {} functions {}",
                        missing.len(),
                        yellow("missing bytecode blobs")
                    );
                }
            }
        } else {
            println!("  compsys:     {}", yellow("no cache"));
        }

        if let Some(ref cache) = self.plugin_cache {
            let (plugins, functions) = cache.stats();
            println!(
                "  plugins:     {} plugins, {} cached functions  {}",
                plugins,
                functions,
                green("OK")
            );
        } else {
            println!("  plugins:     {}", yellow("no cache"));
        }
        println!();

        // --- Shell State ---
        println!("{}", bold("Shell State"));
        println!("  aliases:     {}", self.aliases.len());
        println!("  global:      {} aliases", self.global_aliases.len());
        println!("  suffix:      {} aliases", self.suffix_aliases.len());
        println!("  variables:   {}", self.variables.len());
        println!("  arrays:      {}", self.arrays.len());
        println!("  assoc:       {}", self.assoc_arrays.len());
        println!(
            "  options:     {} set",
            self.options.iter().filter(|(_, v)| **v).count()
        );
        println!("  traps:       {} active", self.traps.len());
        println!(
            "  hooks:       {} registered",
            self.hook_functions.values().map(|v| v.len()).sum::<usize>()
        );
        println!();

        // --- Log ---
        println!("{}", bold("Log"));
        let log_path = crate::log::log_path();
        if log_path.exists() {
            let size = std::fs::metadata(&log_path).map(|m| m.len()).unwrap_or(0);
            println!("  {}  {} bytes", log_path.display(), size);
        } else {
            println!("  {}", dim("no log file yet"));
        }
        println!();

        // --- Profiling ---
        println!("{}", bold("Profiling"));
        println!(
            "  chrome tracing: {}",
            if crate::log::profiling_enabled() {
                green("enabled")
            } else {
                dim("disabled")
            }
        );
        println!(
            "  flamegraph:     {}",
            if crate::log::flamegraph_enabled() {
                green("enabled")
            } else {
                dim("disabled")
            }
        );
        println!(
            "  prometheus:     {}",
            if crate::log::prometheus_enabled() {
                green("enabled")
            } else {
                dim("disabled")
            }
        );
        println!();

        0
    }

    /// dbview — browse zshrs SQLite cache tables without SQL.
    ///
    /// Usage:
    ///   dbview                      — list all tables and row counts
    ///   dbview autoloads             — dump autoloads table (name, source, body len, ast len)
    ///   dbview autoloads _git        — show single row by name
    ///   dbview comps                 — dump comps table
    ///   dbview history               — recent history entries
    ///   dbview history <pattern>     — search history
    ///   dbview plugins               — plugin cache entries
    ///   dbview executables            — PATH executables cache
    ///   dbview <table> --count       — just the count
    fn builtin_dbview(&self, args: &[String]) -> i32 {
        let bold = |s: &str| format!("\x1b[1m{}\x1b[0m", s);
        let dim = |s: &str| format!("\x1b[2m{}\x1b[0m", s);
        let cyan = |s: &str| format!("\x1b[36m{}\x1b[0m", s);
        let green = |s: &str| format!("\x1b[32m{}\x1b[0m", s);
        let yellow = |s: &str| format!("\x1b[33m{}\x1b[0m", s);

        if args.is_empty() {
            // List all tables with row counts
            println!("{}", bold("zshrs SQLite caches"));
            println!();

            if let Some(ref cache) = self.compsys_cache {
                println!("  {} {}", bold("compsys.db"), dim("(completion cache)"));
                if let Ok(n) = cache.count_table("autoloads") {
                    let bc_count = cache
                        .count_table_where("autoloads", "bytecode IS NOT NULL")
                        .unwrap_or(0);
                    println!("    autoloads:    {:>6} rows  ({} compiled)", n, bc_count);
                }
                if let Ok(n) = cache.count_table("comps") {
                    println!("    comps:        {:>6} rows", n);
                }
                if let Ok(n) = cache.count_table("services") {
                    println!("    services:     {:>6} rows", n);
                }
                if let Ok(n) = cache.count_table("patcomps") {
                    println!("    patcomps:     {:>6} rows", n);
                }
                if let Ok(n) = cache.count_table("executables") {
                    println!("    executables:  {:>6} rows", n);
                }
                if let Ok(n) = cache.count_table("zstyles") {
                    println!("    zstyles:      {:>6} rows", n);
                }
                println!();
            }

            if let Some(ref engine) = self.history {
                println!("  {} {}", bold("history.db"), dim("(command history)"));
                if let Ok(n) = engine.count() {
                    println!("    entries:      {:>6} rows", n);
                }
                println!();
            }

            if let Some(ref cache) = self.plugin_cache {
                let (plugins, functions) = cache.stats();
                println!("  {} {}", bold("plugins.db"), dim("(plugin source cache)"));
                println!("    plugins:      {:>6} rows", plugins);
                println!("    functions:    {:>6} rows", functions);
                println!();
            }

            println!("  Usage: {} <table> [name] [--count]", cyan("dbview"));
            return 0;
        }

        let table = args[0].as_str();
        let filter = args.get(1).map(|s| s.as_str());
        let count_only = args.iter().any(|a| a == "--count" || a == "-c");

        match table {
            "autoloads" => {
                let Some(ref cache) = self.compsys_cache else {
                    eprintln!("dbview: no compsys cache");
                    return 1;
                };

                if count_only {
                    let n = cache.count_table("autoloads").unwrap_or(0);
                    println!("{}", n);
                    return 0;
                }

                if let Some(name) = filter {
                    // Single row lookup
                    match cache.get_autoload(name) {
                        Ok(Some(stub)) => {
                            println!("{}", bold(&format!("autoload: {}", name)));
                            println!("  source:   {}", stub.source);
                            println!(
                                "  body:     {} bytes",
                                stub.body.as_ref().map(|b| b.len()).unwrap_or(0)
                            );
                            match cache.get_autoload_bytecode(name) {
                                Ok(Some(blob)) => {
                                    println!("  bytecode: {} {} bytes", green("YES"), blob.len())
                                }
                                _ => println!("  bytecode: {}", yellow("NULL")),
                            }
                            // Show first few lines of body
                            if let Some(ref body) = stub.body {
                                println!("  preview:");
                                for (i, line) in body.lines().take(10).enumerate() {
                                    println!("    {:>3}: {}", i + 1, dim(line));
                                }
                                let total = body.lines().count();
                                if total > 10 {
                                    println!("    {} ({} more lines)", dim("..."), total - 10);
                                }
                            }
                        }
                        _ => {
                            eprintln!("dbview: autoload '{}' not found", name);
                            return 1;
                        }
                    }
                    return 0;
                }

                // Dump all autoloads
                let conn = &cache.conn();
                match conn.prepare("SELECT name, source, length(body), length(bytecode) FROM autoloads ORDER BY name LIMIT 200") {
                    Ok(mut stmt) => {
                        let rows = stmt.query_map([], |row| {
                            Ok((
                                row.get::<_, String>(0)?,
                                row.get::<_, String>(1)?,
                                row.get::<_, Option<i64>>(2)?,
                                row.get::<_, Option<i64>>(3)?,
                            ))
                        });
                        if let Ok(rows) = rows {
                            println!("{:<40} {:>8} {:>8}  {}", bold("NAME"), bold("BODY"), bold("BYTECODE"), bold("SOURCE"));
                            let mut count = 0;
                            for row in rows.flatten() {
                                let (name, source, body_len, ast_len) = row;
                                let ast_str = match ast_len {
                                    Some(n) => green(&format!("{:>8}", n)),
                                    None => yellow(&format!("{:>8}", "NULL")),
                                };
                                let body_str = match body_len {
                                    Some(n) => format!("{:>8}", n),
                                    None => dim("NULL").to_string(),
                                };
                                // Truncate source path for display
                                let src_short = if source.len() > 50 {
                                    format!("...{}", &source[source.len() - 47..])
                                } else {
                                    source
                                };
                                println!("{:<40} {} {}  {}", name, body_str, ast_str, dim(&src_short));
                                count += 1;
                            }
                            println!("\n{} rows shown (LIMIT 200)", count);
                        }
                    }
                    Err(e) => {
                        eprintln!("dbview: query failed: {}", e);
                        return 1;
                    }
                }
            }

            "comps" => {
                let Some(ref cache) = self.compsys_cache else {
                    eprintln!("dbview: no compsys cache");
                    return 1;
                };
                if count_only {
                    println!("{}", cache.count_table("comps").unwrap_or(0));
                    return 0;
                }
                let conn = cache.conn();
                let query = if let Some(pat) = filter {
                    format!("SELECT command, function FROM comps WHERE command LIKE '%{}%' ORDER BY command LIMIT 100", pat)
                } else {
                    "SELECT command, function FROM comps ORDER BY command LIMIT 100".to_string()
                };
                match conn.prepare(&query) {
                    Ok(mut stmt) => {
                        println!("{:<40} {}", bold("COMMAND"), bold("FUNCTION"));
                        let rows = stmt.query_map([], |row| {
                            Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?))
                        });
                        if let Ok(rows) = rows {
                            for row in rows.flatten() {
                                println!("{:<40} {}", row.0, cyan(&row.1));
                            }
                        }
                    }
                    Err(e) => {
                        eprintln!("dbview: {}", e);
                        return 1;
                    }
                }
            }

            "executables" => {
                let Some(ref cache) = self.compsys_cache else {
                    eprintln!("dbview: no compsys cache");
                    return 1;
                };
                if count_only {
                    println!("{}", cache.count_table("executables").unwrap_or(0));
                    return 0;
                }
                let conn = cache.conn();
                let query = if let Some(pat) = filter {
                    format!("SELECT name, path FROM executables WHERE name LIKE '%{}%' ORDER BY name LIMIT 100", pat)
                } else {
                    "SELECT name, path FROM executables ORDER BY name LIMIT 100".to_string()
                };
                match conn.prepare(&query) {
                    Ok(mut stmt) => {
                        println!("{:<30} {}", bold("NAME"), bold("PATH"));
                        let rows = stmt.query_map([], |row| {
                            Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?))
                        });
                        if let Ok(rows) = rows {
                            for row in rows.flatten() {
                                println!("{:<30} {}", row.0, dim(&row.1));
                            }
                        }
                    }
                    Err(e) => {
                        eprintln!("dbview: {}", e);
                        return 1;
                    }
                }
            }

            "history" => {
                let Some(ref engine) = self.history else {
                    eprintln!("dbview: no history engine");
                    return 1;
                };
                if count_only {
                    println!("{}", engine.count().unwrap_or(0));
                    return 0;
                }
                if let Some(pat) = filter {
                    if let Ok(entries) = engine.search(pat, 20) {
                        for e in entries {
                            println!(
                                "  {} {} {}",
                                dim(&e.timestamp.to_string()),
                                cyan(&e.command),
                                dim(&format!("[{}]", e.exit_code.unwrap_or(0)))
                            );
                        }
                    }
                } else if let Ok(entries) = engine.recent(20) {
                    for e in entries {
                        println!(
                            "  {} {} {}",
                            dim(&e.timestamp.to_string()),
                            cyan(&e.command),
                            dim(&format!("[{}]", e.exit_code.unwrap_or(0)))
                        );
                    }
                }
            }

            "plugins" => {
                let Some(ref cache) = self.plugin_cache else {
                    eprintln!("dbview: no plugin cache");
                    return 1;
                };
                let (plugins, functions) = cache.stats();
                println!("{} plugins, {} cached functions", plugins, functions);
            }

            _ => {
                eprintln!("dbview: unknown table '{}'. Available: autoloads, comps, executables, history, plugins", table);
                return 1;
            }
        }

        0
    }

    /// profile — in-process command profiling with nanosecond accuracy.
    ///
    /// Unlike `time` (which measures one command) or `zprof` (which only
    /// profiles function calls), `profile` traces every execute_command,
    /// expansion, glob, and builtin dispatch inside the block.
    ///
    /// Usage:
    ///   profile { commands }     — profile a block
    ///   profile -s 'script'     — profile a script string
    ///   profile -f func         — profile a function call
    ///   profile --clear         — clear accumulated profile data
    ///   profile --dump          — show accumulated profile data
    fn builtin_profile(&mut self, args: &[String]) -> i32 {
        let bold = |s: &str| format!("\x1b[1m{}\x1b[0m", s);
        let dim = |s: &str| format!("\x1b[2m{}\x1b[0m", s);
        let cyan = |s: &str| format!("\x1b[36m{}\x1b[0m", s);
        let yellow = |s: &str| format!("\x1b[33m{}\x1b[0m", s);

        if args.is_empty() {
            println!("Usage: profile {{ commands }}");
            println!("       profile -s 'script string'");
            println!("       profile -f function_name [args...]");
            println!("       profile --clear");
            println!("       profile --dump");
            return 0;
        }

        if args[0] == "--clear" {
            self.profiler = crate::zprof::Profiler::new();
            println!("profile data cleared");
            return 0;
        }

        if args[0] == "--dump" {
            let (_, output) = crate::zprof::builtin_zprof(
                &mut self.profiler,
                &crate::zprof::ZprofOptions { clear: false },
            );
            if !output.is_empty() {
                print!("{}", output);
            } else {
                println!("{}", dim("no profile data"));
            }
            return 0;
        }

        // Determine what to profile
        let code = if args[0] == "-s" {
            // profile -s 'script string'
            if args.len() < 2 {
                eprintln!("profile: -s requires a script string");
                return 1;
            }
            args[1..].join(" ")
        } else if args[0] == "-f" {
            // profile -f func_name [args...]
            if args.len() < 2 {
                eprintln!("profile: -f requires a function name");
                return 1;
            }
            args[1..].join(" ")
        } else {
            // profile { commands } — args is the block body
            args.join(" ")
        };

        // Enable profiling, run, collect results
        let was_enabled = self.profiling_enabled;
        self.profiling_enabled = true;
        self.profiler = crate::zprof::Profiler::new(); // fresh data for this run

        let t0 = std::time::Instant::now();
        let result = self.execute_script(&code);
        let elapsed = t0.elapsed();
        let status = match result {
            Ok(s) => s,
            Err(e) => {
                eprintln!("profile: {}", e);
                1
            }
        };

        // Collect timing data
        println!();
        println!("{}", bold("profile results"));
        println!("{}", dim(&"─".repeat(60)));
        let dur_str = if elapsed.as_secs() > 0 {
            format!("{:.3}s", elapsed.as_secs_f64())
        } else if elapsed.as_millis() > 0 {
            format!("{:.3}ms", elapsed.as_secs_f64() * 1000.0)
        } else {
            format!("{:.1}µs", elapsed.as_secs_f64() * 1_000_000.0)
        };
        println!("  total:     {}", cyan(&dur_str));
        println!("  status:    {}", status);
        println!();

        // Show function-level breakdown from profiler
        let (_, output) = crate::zprof::builtin_zprof(
            &mut self.profiler,
            &crate::zprof::ZprofOptions { clear: false },
        );
        if !output.is_empty() {
            println!("{}", bold("function breakdown"));
            print!("{}", output);
        }

        // Per-command breakdown from tracing (if tracing is at debug level)
        println!();
        println!(
            "  {} set ZSHRS_LOG=trace for per-command tracing",
            yellow("tip:")
        );
        println!(
            "  {} output: {}",
            dim("log"),
            dim(&crate::log::log_path().display().to_string())
        );

        self.profiling_enabled = was_enabled;
        status
    }

    // ═══════════════════════════════════════════════════════════════════
    // AOP INTERCEPT — the killer builtin
    // ═══════════════════════════════════════════════════════════════════

    /// Check intercepts for a command. Returns Some(result) if an around
    /// advice fully handled the command, None to proceed normally.
    fn run_intercepts(
        &mut self,
        cmd_name: &str,
        full_cmd: &str,
        args: &[String],
    ) -> Option<Result<i32, String>> {
        // Collect matching intercepts (clone to avoid borrow issues)
        let matching: Vec<Intercept> = self
            .intercepts
            .iter()
            .filter(|i| intercept_matches(&i.pattern, cmd_name, full_cmd))
            .cloned()
            .collect();

        if matching.is_empty() {
            return None;
        }

        // Set INTERCEPT_NAME and INTERCEPT_ARGS for advice code
        self.variables
            .insert("INTERCEPT_NAME".to_string(), cmd_name.to_string());
        self.variables
            .insert("INTERCEPT_ARGS".to_string(), args.join(" "));
        self.variables
            .insert("INTERCEPT_CMD".to_string(), full_cmd.to_string());

        // Run before advice
        for advice in matching
            .iter()
            .filter(|i| matches!(i.kind, AdviceKind::Before))
        {
            let _ = self.execute_advice(&advice.code);
        }

        // Check for around advice — first match wins
        let around = matching
            .iter()
            .find(|i| matches!(i.kind, AdviceKind::Around));

        let t0 = std::time::Instant::now();

        let result = if let Some(advice) = around {
            // Around advice: set INTERCEPT_PROCEED flag, run advice code.
            // If advice calls `intercept_proceed`, the original command runs.
            self.variables
                .insert("__intercept_proceed".to_string(), "0".to_string());
            let advice_result = self.execute_advice(&advice.code);

            // Check if intercept_proceed was called
            let proceeded = self
                .variables
                .get("__intercept_proceed")
                .map(|v| v == "1")
                .unwrap_or(false);

            if proceeded {
                // The original command was already executed inside the advice
                advice_result
            } else {
                // Advice didn't call proceed — command was suppressed
                advice_result
            }
        } else {
            // No around advice — run the original command.
            // We return None to let the normal dispatch continue.
            // But we still need after advice to fire, so we can't return None here
            // if there are after advices. Run the command ourselves.
            let has_after = matching.iter().any(|i| matches!(i.kind, AdviceKind::After));
            if !has_after {
                // Only before advice, no after — let normal dispatch continue
                return None;
            }

            // Has after advice — we must run the command and then run after advice
            self.run_original_command(cmd_name, args)
        };

        let elapsed = t0.elapsed();

        // Set timing variable for after advice
        let ms = elapsed.as_secs_f64() * 1000.0;
        self.variables
            .insert("INTERCEPT_MS".to_string(), format!("{:.3}", ms));
        self.variables
            .insert("INTERCEPT_US".to_string(), format!("{:.0}", ms * 1000.0));

        // Run after advice
        for advice in matching
            .iter()
            .filter(|i| matches!(i.kind, AdviceKind::After))
        {
            let _ = self.execute_advice(&advice.code);
        }

        // Clean up
        self.variables.remove("INTERCEPT_NAME");
        self.variables.remove("INTERCEPT_ARGS");
        self.variables.remove("INTERCEPT_CMD");
        self.variables.remove("INTERCEPT_MS");
        self.variables.remove("INTERCEPT_US");
        self.variables.remove("__intercept_proceed");

        Some(result)
    }

    /// Execute the original command (used by around/after intercept dispatch).
    /// Execute advice code — dispatches @ prefix to stryke (fat binary),
    /// everything else to the shell parser. No fork. Machine code speed.
    fn execute_advice(&mut self, code: &str) -> Result<i32, String> {
        let code = code.trim();
        if code.starts_with('@') {
            let stryke_code = code.trim_start_matches('@').trim();
            if let Some(status) = crate::try_stryke_dispatch(stryke_code) {
                self.last_status = status;
                return Ok(status);
            }
            // No stryke handler (thin binary) — fall through to shell
        }
        self.execute_script(code)
    }

    fn run_original_command(&mut self, cmd_name: &str, args: &[String]) -> Result<i32, String> {
        // Function dispatch via the compiled pipeline (functions_compiled
        // first, falls back to legacy AST recompile if needed).
        if let Some(status) = self.dispatch_function_call(cmd_name, args) {
            return Ok(status);
        }
        // External command
        self.execute_external(cmd_name, &args.to_vec(), &[])
    }

    /// intercept builtin — register AOP advice on commands.
    ///
    /// Usage:
    ///   intercept before <pattern> { code }
    ///   intercept after <pattern> { code }
    ///   intercept around <pattern> { code }
    ///   intercept list                       — show all intercepts
    ///   intercept remove <id>                — remove by ID
    ///   intercept clear                      — remove all
    fn builtin_intercept(&mut self, args: &[String]) -> i32 {
        if args.is_empty() {
            println!("Usage: intercept <before|after|around> <pattern> {{ code }}");
            println!("       intercept list | remove <id> | clear");
            return 0;
        }

        match args[0].as_str() {
            "list" => {
                if self.intercepts.is_empty() {
                    println!("no intercepts registered");
                } else {
                    let bold = |s: &str| format!("\x1b[1m{}\x1b[0m", s);
                    let cyan = |s: &str| format!("\x1b[36m{}\x1b[0m", s);
                    println!(
                        "{:>4}  {:<8}  {:<20}  {}",
                        bold("ID"),
                        bold("KIND"),
                        bold("PATTERN"),
                        bold("CODE")
                    );
                    for i in &self.intercepts {
                        let kind = match i.kind {
                            AdviceKind::Before => "before",
                            AdviceKind::After => "after",
                            AdviceKind::Around => "around",
                        };
                        let code_preview = if i.code.len() > 40 {
                            format!("{}...", &i.code[..37])
                        } else {
                            i.code.clone()
                        };
                        println!(
                            "{:>4}  {:<8}  {:<20}  {}",
                            cyan(&i.id.to_string()),
                            kind,
                            i.pattern,
                            code_preview
                        );
                    }
                }
                0
            }
            "clear" => {
                let count = self.intercepts.len();
                self.intercepts.clear();
                println!("cleared {} intercepts", count);
                0
            }
            "remove" => {
                if args.len() < 2 {
                    eprintln!("intercept remove: requires ID");
                    return 1;
                }
                if let Ok(id) = args[1].parse::<u32>() {
                    let before = self.intercepts.len();
                    self.intercepts.retain(|i| i.id != id);
                    if self.intercepts.len() < before {
                        println!("removed intercept {}", id);
                        0
                    } else {
                        eprintln!("intercept: no intercept with ID {}", id);
                        1
                    }
                } else {
                    eprintln!("intercept remove: invalid ID");
                    1
                }
            }
            "before" | "after" | "around" => {
                let kind = match args[0].as_str() {
                    "before" => AdviceKind::Before,
                    "after" => AdviceKind::After,
                    "around" => AdviceKind::Around,
                    _ => unreachable!(),
                };

                if args.len() < 3 {
                    eprintln!("intercept {}: requires <pattern> {{ code }}", args[0]);
                    return 1;
                }

                let pattern = args[1].clone();
                // Join remaining args as the code (handles { code } or 'code')
                let code = args[2..].join(" ");
                // Strip surrounding braces if present
                let code = code.trim().to_string();
                let code = if code.starts_with('{') && code.ends_with('}') {
                    code[1..code.len() - 1].trim().to_string()
                } else {
                    code
                };

                let id = self.intercepts.iter().map(|i| i.id).max().unwrap_or(0) + 1;
                self.intercepts.push(Intercept {
                    pattern,
                    kind: kind.clone(),
                    code: code.clone(),
                    id,
                });

                let kind_str = match kind {
                    AdviceKind::Before => "before",
                    AdviceKind::After => "after",
                    AdviceKind::Around => "around",
                };
                println!(
                    "intercept #{}: {} {} → {}",
                    id,
                    kind_str,
                    self.intercepts.last().unwrap().pattern,
                    if code.len() > 50 {
                        format!("{}...", &code[..47])
                    } else {
                        code
                    }
                );
                0
            }
            _ => {
                eprintln!(
                    "intercept: unknown subcommand '{}'. Use before|after|around|list|remove|clear",
                    args[0]
                );
                1
            }
        }
    }

    /// intercept_proceed — called from around advice to execute the original command.
    fn builtin_intercept_proceed(&mut self, _args: &[String]) -> i32 {
        self.variables
            .insert("__intercept_proceed".to_string(), "1".to_string());
        // Run the original command using saved INTERCEPT_NAME/INTERCEPT_ARGS
        let cmd_name = self
            .variables
            .get("INTERCEPT_NAME")
            .cloned()
            .unwrap_or_default();
        let args_str = self
            .variables
            .get("INTERCEPT_ARGS")
            .cloned()
            .unwrap_or_default();
        let args: Vec<String> = if args_str.is_empty() {
            Vec::new()
        } else {
            args_str.split_whitespace().map(|s| s.to_string()).collect()
        };
        match self.run_original_command(&cmd_name, &args) {
            Ok(status) => status,
            Err(e) => {
                eprintln!("intercept_proceed: {}", e);
                1
            }
        }
    }

    // ═══════════════════════════════════════════════════════════════════
    // CONCURRENT PRIMITIVES — ship work to the worker pool from shell
    // No stryke dependency. Pure zshrs. Thin binary gets full parallelism.
    // ═══════════════════════════════════════════════════════════════════

    /// async { cmd } — run command on worker pool, return job ID immediately.
    /// Output captured in background, retrieve with `await $id`.
    ///
    /// Usage:
    ///   id=$(async 'sleep 2; echo done')
    ///   ... do other work ...
    ///   result=$(await $id)
    fn builtin_async(&mut self, args: &[String]) -> i32 {
        if args.is_empty() {
            eprintln!("async: requires a command string");
            return 1;
        }

        let code = args.join(" ");
        let id = self.next_async_id;
        self.next_async_id += 1;

        let (tx, rx) = crossbeam_channel::bounded::<(i32, String)>(1);
        let pool = std::sync::Arc::clone(&self.worker_pool);

        pool.submit(move || {
            // Execute in a subprocess to capture stdout
            use std::process::{Command, Stdio};
            let output = Command::new("sh")
                .args(["-c", &code])
                .stdout(Stdio::piped())
                .stderr(Stdio::inherit())
                .output();
            match output {
                Ok(out) => {
                    let stdout = String::from_utf8_lossy(&out.stdout).to_string();
                    let status = out.status.code().unwrap_or(1);
                    let _ = tx.send((status, stdout));
                }
                Err(_) => {
                    let _ = tx.send((127, String::new()));
                }
            }
        });

        self.async_jobs.insert(id, rx);
        // Print the job ID so it can be captured: id=$(async 'cmd')
        println!("{}", id);
        0
    }

    /// await $id — block until async job completes, print its stdout, return its status.
    ///
    /// Usage:
    ///   id=$(async 'expensive_command')
    ///   await $id    # blocks until done, prints output
    ///   echo $?      # exit status of the async command
    fn builtin_await(&mut self, args: &[String]) -> i32 {
        if args.is_empty() {
            eprintln!("await: requires a job ID");
            return 1;
        }

        let id: u32 = match args[0].parse() {
            Ok(n) => n,
            Err(_) => {
                eprintln!("await: invalid job ID '{}'", args[0]);
                return 1;
            }
        };

        let rx = match self.async_jobs.remove(&id) {
            Some(rx) => rx,
            None => {
                eprintln!("await: no async job with ID {}", id);
                return 1;
            }
        };

        // Block until the job completes
        match rx.recv() {
            Ok((status, stdout)) => {
                if !stdout.is_empty() {
                    print!("{}", stdout);
                }
                self.last_status = status;
                status
            }
            Err(_) => {
                eprintln!("await: job {} died without result", id);
                1
            }
        }
    }

    /// pmap 'cmd {}' arg1 arg2 arg3 — parallel map across worker pool.
    /// Runs `cmd` for each argument, replacing `{}` with the argument.
    /// Output is collected in order. Returns 0 if all succeed.
    ///
    /// Usage:
    ///   pmap 'gzip {}' *.log
    ///   pmap 'echo {}' a b c d
    ///   ls *.rs | pmap 'wc -l {}'
    fn builtin_pmap(&mut self, args: &[String]) -> i32 {
        if args.len() < 2 {
            eprintln!("pmap: requires 'command {{}}' followed by arguments");
            return 1;
        }

        let template = &args[0];
        let items = &args[1..];

        // Compile template once, execute for each item on VM — no forks
        let mut results: Vec<(i32, String)> = Vec::with_capacity(items.len());

        for item in items {
            let cmd = template.replace("{}", item);
            // Phase 2 migration: ZshParser + ZshCompiler.
            let mut parser = crate::parser::ZshParser::new(&cmd);
            match parser.parse() {
                Ok(prog) => {
                    let compiler = crate::compile_zsh::ZshCompiler::new();
                    let chunk = compiler.compile(&prog);

                    // Capture stdout
                    let output = Vec::new();
                    let status = {
                        let mut vm = fusevm::VM::new(chunk);
                        register_builtins(&mut vm);
                        let _ctx = ExecutorContext::enter(self);
                        match vm.run() {
                            fusevm::VMResult::Ok(_) | fusevm::VMResult::Halted => vm.last_status,
                            fusevm::VMResult::Error(_) => 1,
                        }
                    };
                    results.push((status, String::from_utf8_lossy(&output).to_string()));
                }
                Err(errs) => {
                    let msg = errs
                        .first()
                        .map(|e| format!("{}", e))
                        .unwrap_or_else(|| "parse error".to_string());
                    eprintln!("pmap: parse error: {}", msg);
                    results.push((1, String::new()));
                }
            }
        }

        let mut any_fail = false;
        for (status, stdout) in results {
            if !stdout.is_empty() {
                print!("{}", stdout);
            }
            if status != 0 {
                any_fail = true;
            }
        }

        if any_fail {
            1
        } else {
            0
        }
    }

    /// pgrep 'pattern' arg1 arg2 ... — parallel grep/filter across worker pool.
    /// Runs the pattern command for each argument, prints args where command succeeds.
    ///
    /// Usage:
    ///   pgrep 'test -f {}' /path/a /path/b /path/c
    ///   pgrep 'grep -q TODO {}' *.rs
    fn builtin_pgrep(&mut self, args: &[String]) -> i32 {
        if args.len() < 2 {
            eprintln!("pgrep: requires 'test_command {{}}' followed by arguments");
            return 1;
        }

        let template = &args[0];
        let items = &args[1..];

        // Compile and run on VM — no forks. Phase 2: ZshParser+ZshCompiler.
        for item in items {
            let cmd = template.replace("{}", item);
            let mut parser = crate::parser::ZshParser::new(&cmd);
            if let Ok(prog) = parser.parse() {
                let compiler = crate::compile_zsh::ZshCompiler::new();
                let chunk = compiler.compile(&prog);

                let mut vm = fusevm::VM::new(chunk);
                register_builtins(&mut vm);
                let _ctx = ExecutorContext::enter(self);
                let status = match vm.run() {
                    fusevm::VMResult::Ok(_) | fusevm::VMResult::Halted => vm.last_status,
                    fusevm::VMResult::Error(_) => 1,
                };

                if status == 0 {
                    println!("{}", item);
                }
            }
        }

        0
    }

    /// peach 'cmd {}' arg1 arg2 ... — parallel for-each, no output ordering.
    /// Like pmap but doesn't collect output — fire-and-forget, print as completed.
    ///
    /// Usage:
    ///   peach 'convert {} {}.png' *.svg
    ///   peach 'rsync -a {} remote:{}' dir1 dir2 dir3
    fn builtin_peach(&mut self, args: &[String]) -> i32 {
        if args.len() < 2 {
            eprintln!("peach: requires 'command {{}}' followed by arguments");
            return 1;
        }

        let template = &args[0];
        let items = &args[1..];

        // Compile and run on VM — no forks, fire-and-forget style.
        // Phase 2: ZshParser+ZshCompiler.
        let mut any_fail = false;

        for item in items {
            let cmd = template.replace("{}", item);
            let mut parser = crate::parser::ZshParser::new(&cmd);
            if let Ok(prog) = parser.parse() {
                let compiler = crate::compile_zsh::ZshCompiler::new();
                let chunk = compiler.compile(&prog);

                let mut vm = fusevm::VM::new(chunk);
                register_builtins(&mut vm);
                let _ctx = ExecutorContext::enter(self);
                let status = match vm.run() {
                    fusevm::VMResult::Ok(_) | fusevm::VMResult::Halted => vm.last_status,
                    fusevm::VMResult::Error(_) => 1,
                };

                if status != 0 {
                    any_fail = true;
                }
            } else {
                any_fail = true;
            }
        }

        if any_fail {
            1
        } else {
            0
        }
    }

    /// barrier cmd1 ::: cmd2 ::: cmd3 — run commands in parallel, wait for ALL to complete.
    /// Returns the worst (highest) exit status.
    ///
    /// Usage:
    ///   barrier 'make -C proj1' ::: 'make -C proj2' ::: 'make -C proj3'
    ///   barrier 'npm test' ::: 'cargo test' ::: 'pytest'
    fn builtin_barrier(&mut self, args: &[String]) -> i32 {
        if args.is_empty() {
            eprintln!("barrier: requires commands separated by :::");
            return 1;
        }

        // Split on ::: delimiter
        let mut commands: Vec<String> = Vec::new();
        let mut current = String::new();
        for arg in args {
            if arg == ":::" {
                if !current.is_empty() {
                    commands.push(current.trim().to_string());
                    current.clear();
                }
            } else {
                if !current.is_empty() {
                    current.push(' ');
                }
                current.push_str(arg);
            }
        }
        if !current.is_empty() {
            commands.push(current.trim().to_string());
        }

        if commands.is_empty() {
            return 0;
        }

        // Ship all to pool
        let mut receivers = Vec::with_capacity(commands.len());
        for cmd in &commands {
            let cmd = cmd.clone();
            let rx = self.worker_pool.submit_with_result(move || {
                use std::process::{Command, Stdio};
                Command::new("sh")
                    .args(["-c", &cmd])
                    .stdout(Stdio::inherit())
                    .stderr(Stdio::inherit())
                    .status()
                    .map(|s| s.code().unwrap_or(1))
                    .unwrap_or(127)
            });
            receivers.push(rx);
        }

        // Wait for all — return worst status
        let mut worst = 0i32;
        for rx in receivers {
            if let Ok(status) = rx.recv() {
                if status > worst {
                    worst = status;
                }
            }
        }

        self.last_status = worst;
        worst
    }

    /// help - display help for builtins (bash)
    fn builtin_help(&self, args: &[String]) -> i32 {
        if args.is_empty() {
            println!("zshrs shell builtins:");
            println!("");
            println!("  alias, bg, bind, break, builtin, cd, command, continue,");
            println!("  declare, dirs, disown, echo, enable, eval, exec, exit,");
            println!("  export, false, fc, fg, getopts, hash, help, history,");
            println!("  jobs, kill, let, local, logout, popd, printf, pushd,");
            println!("  pwd, read, readonly, return, set, shift, shopt, source,");
            println!("  suspend, test, times, trap, true, type, typeset, ulimit,");
            println!("  umask, unalias, unset, wait, whence, where, which");
            println!("");
            println!("Type 'help name' for more information about 'name'.");
            return 0;
        }

        let cmd = &args[0];
        match cmd.as_str() {
            "cd" => println!("cd: cd [-L|-P] [dir]\n    Change the shell working directory."),
            "echo" => println!("echo: echo [-neE] [arg ...]\n    Write arguments to standard output."),
            "export" => println!("export: export [-fn] [name[=value] ...]\n    Set export attribute for shell variables."),
            "alias" => println!("alias: alias [-p] [name[=value] ...]\n    Define or display aliases."),
            "history" => println!("history: history [-c] [-d offset] [n]\n    Display or manipulate the history list."),
            "jobs" => println!("jobs: jobs [-lnprs] [jobspec ...]\n    Display status of jobs."),
            "kill" => println!("kill: kill [-s sigspec | -n signum | -sigspec] pid | jobspec ...\n    Send a signal to a job."),
            "read" => println!("read: read [-ers] [-a array] [-d delim] [-i text] [-n nchars] [-N nchars] [-p prompt] [-t timeout] [-u fd] [name ...]\n    Read a line from standard input."),
            "set" => println!("set: set [-abefhkmnptuvxBCHP] [-o option-name] [--] [arg ...]\n    Set or unset values of shell options and positional parameters."),
            "test" | "[" => println!("test: test [expr]\n    Evaluate conditional expression."),
            "type" => println!("type: type [-afptP] name [name ...]\n    Display information about command type."),
            _ => println!("{}: no help available", cmd),
        }
        0
    }

    /// readarray/mapfile - read lines into array (bash)
    fn builtin_readarray(&mut self, args: &[String]) -> i32 {
        // bash readarray / mapfile: read lines from a fd into an array.
        // Direct port of bash's read_builtin_array_loadable. zsh has no
        // direct equivalent (use `read -A`), but plugin code that
        // toggles between bash/zsh frequently calls this.
        use std::io::Read as IoRead;

        let mut array_name = "MAPFILE".to_string();
        let mut delimiter: u8 = b'\n';
        let mut count = 0usize; // 0 = unlimited
        let mut skip = 0usize;
        let mut strip_trailing = false;
        let mut callback: Option<String> = None;
        let mut callback_quantum = 0usize;
        let mut fd: i32 = 0;

        let mut i = 0;
        while i < args.len() {
            match args[i].as_str() {
                "-d" => {
                    i += 1;
                    if i < args.len() && !args[i].is_empty() {
                        delimiter = args[i].as_bytes()[0];
                    }
                }
                "-n" => {
                    i += 1;
                    if i < args.len() {
                        count = args[i].parse().unwrap_or(0);
                    }
                }
                "-O" => {
                    i += 1;
                    // Origin - start index (ignored, we always start at 0)
                }
                "-s" => {
                    i += 1;
                    if i < args.len() {
                        skip = args[i].parse().unwrap_or(0);
                    }
                }
                "-t" => strip_trailing = true,
                "-C" => {
                    i += 1;
                    if i < args.len() {
                        callback = Some(args[i].clone());
                    }
                }
                "-c" => {
                    i += 1;
                    if i < args.len() {
                        callback_quantum = args[i].parse().unwrap_or(5000);
                    }
                }
                "-u" => {
                    i += 1;
                    if i < args.len() {
                        fd = args[i].parse().unwrap_or(0);
                    }
                }
                s if !s.starts_with('-') => {
                    array_name = s.to_string();
                }
                _ => {}
            }
            i += 1;
        }

        // Read entire input from the chosen fd, then split on delim.
        // Using libc::read on the raw fd so -u N picks any open fd
        // (was hardcoded stdin).
        let mut input: Vec<u8> = Vec::new();
        if fd == 0 {
            let stdin = std::io::stdin();
            let mut handle = stdin.lock();
            if handle.read_to_end(&mut input).is_err() {
                return 1;
            }
        } else {
            let mut buf = [0u8; 8192];
            loop {
                let n = unsafe {
                    libc::read(fd, buf.as_mut_ptr() as *mut libc::c_void, buf.len())
                };
                if n <= 0 {
                    break;
                }
                input.extend_from_slice(&buf[..n as usize]);
            }
        }

        // Split on `delimiter`. The delimiter byte itself is NOT
        // included in each element (bash splits same way; -t doesn't
        // change inclusion since the delim is already absent).
        let mut lines: Vec<String> = Vec::new();
        let mut line_count = 0usize;
        for chunk in input.split(|b| *b == delimiter) {
            // Skip a trailing empty produced by a final delimiter byte:
            // bash's readarray drops it for `-t` but keeps it otherwise.
            // We emulate by suppressing trailing empties unconditionally
            // when the input ended with the delim — matches the common
            // 'one entry per line' expectation.
            line_count += 1;
            if line_count <= skip {
                continue;
            }
            let mut line = String::from_utf8_lossy(chunk).to_string();
            if strip_trailing {
                while line.ends_with('\n') || line.ends_with('\r') {
                    line.pop();
                }
            }
            lines.push(line);
            if count > 0 && lines.len() >= count {
                break;
            }
        }
        // Drop trailing empty if input ended with delimiter and the
        // user didn't ask for it.
        if input.last() == Some(&delimiter) && lines.last().map(|s| s.is_empty()).unwrap_or(false) {
            lines.pop();
        }

        self.arrays.insert(array_name, lines);
        let _ = (callback, callback_quantum);
        0
    }

    fn builtin_shopt(&mut self, args: &[String]) -> i32 {
        if args.is_empty() {
            // List all shell options. Sorted by name so output is
            // deterministic across runs (was HashMap-iteration-order
            // → flickered between runs and broke `shopt | diff`).
            let mut sorted: Vec<(&String, &bool)> = self.options.iter().collect();
            sorted.sort_by(|a, b| a.0.cmp(b.0));
            for (opt, val) in sorted {
                println!("shopt {} {}", if *val { "-s" } else { "-u" }, opt);
            }
            return 0;
        }

        let mut set = None;
        let mut opts = Vec::new();

        for arg in args {
            match arg.as_str() {
                "-s" => set = Some(true),
                "-u" => set = Some(false),
                "-p" => {
                    // Print option status
                    for opt in &opts {
                        let val = self.options.get(opt).copied().unwrap_or(false);
                        println!("shopt {} {}", if val { "-s" } else { "-u" }, opt);
                    }
                    return 0;
                }
                _ => opts.push(arg.clone()),
            }
        }

        if let Some(enable) = set {
            for opt in &opts {
                self.options.insert(opt.clone(), enable);
            }
        } else {
            // Query options
            for opt in &opts {
                let val = self.options.get(opt).copied().unwrap_or(false);
                println!("shopt {} {}", if val { "-s" } else { "-u" }, opt);
            }
        }
        0
    }

    /// zsh-compatible setopt builtin
    fn builtin_setopt(&mut self, args: &[String]) -> i32 {
        if args.is_empty() {
            // List options that differ from compiled-in defaults (zsh behavior)
            // For default-ON options: show "noOPTION" if currently OFF
            // For default-OFF options: show "OPTION" if currently ON
            let defaults_on = Self::default_on_options();
            let mut diff_opts: Vec<String> = Vec::new();

            for &opt in Self::all_zsh_options() {
                let enabled = self.options.get(opt).copied().unwrap_or(false);
                let is_default_on = defaults_on.contains(&opt);

                if is_default_on && !enabled {
                    // Default ON but currently OFF -> show noOPTION
                    diff_opts.push(format!("no{}", opt));
                } else if !is_default_on && enabled {
                    // Default OFF but currently ON -> show OPTION
                    diff_opts.push(opt.to_string());
                }
            }
            diff_opts.sort();
            for opt in diff_opts {
                println!("{}", opt);
            }
            return 0;
        }

        // `setopt -p` / `setopt -L` — print currently-set options in
        // a form that can be sourced to restore the state. Bash uses -p,
        // zsh accepts both. Output: `setopt OPTION` per line for each
        // currently-set non-default option.
        if args.iter().any(|a| a == "-p" || a == "-L") {
            let defaults_on = Self::default_on_options();
            let mut diff_opts: Vec<String> = Vec::new();
            for &opt in Self::all_zsh_options() {
                let enabled = self.options.get(opt).copied().unwrap_or(false);
                let is_default_on = defaults_on.contains(&opt);
                if is_default_on && !enabled {
                    diff_opts.push(format!("setopt no{}", opt));
                } else if !is_default_on && enabled {
                    diff_opts.push(format!("setopt {}", opt));
                }
            }
            diff_opts.sort();
            for line in diff_opts {
                println!("{}", line);
            }
            return 0;
        }

        let mut use_pattern = false;
        let mut iter = args.iter().peekable();

        while let Some(arg) = iter.next() {
            match arg.as_str() {
                "-m" => use_pattern = true,
                "-o" => {
                    // -o option_name: set option
                    if let Some(opt) = iter.next() {
                        let (name, enable) = Self::normalize_option_name(opt);
                        self.options.insert(name, enable);
                    }
                }
                "+o" => {
                    // +o option_name: unset option
                    if let Some(opt) = iter.next() {
                        let (name, enable) = Self::normalize_option_name(opt);
                        self.options.insert(name, !enable);
                    }
                }
                _ => {
                    if use_pattern {
                        // Match pattern against all options
                        for opt in Self::all_zsh_options() {
                            if Self::option_matches_pattern(opt, arg) {
                                self.options.insert(opt.to_string(), true);
                            }
                        }
                    } else {
                        // zsh: single-letter `-X` / `+X` flags on
                        // setopt are shortcuts for option names from
                        // the option-letter table (mirrors `set`).
                        // `setopt -h` is a no-op accepted silently
                        // (the `h` shortcut maps to `hashcmds`).
                        // zshrs's old default arm rejected ANY `-`
                        // prefixed arg as an unknown name.
                        if arg.len() == 2 && (arg.starts_with('-') || arg.starts_with('+')) {
                            // Single-letter form — accept silently
                            // (already covered for the few we wire
                            // up; the rest are no-ops in `-c` mode).
                            continue;
                        }
                        let (name, enable) = Self::normalize_option_name(arg);
                        // zsh: `setopt nosuchoption` errors with
                        //   `setopt:1: no such option: nosuchoption`
                        // Reject unknown names against the canonical
                        // ZSH_OPTIONS_SET so user scripts get the same
                        // diagnostic. Strip leading `no` first because
                        // `nounset` ↔ `unset` style names are toggles.
                        if !ZSH_OPTIONS_SET.contains(name.as_str()) {
                            eprintln!("zshrs:setopt:1: no such option: {}", arg);
                            return 1;
                        }
                        self.options.insert(name, enable);
                    }
                }
            }
        }
        0
    }

    /// zsh-compatible unsetopt builtin
    fn builtin_unsetopt(&mut self, args: &[String]) -> i32 {
        if args.is_empty() {
            // List all options in the format you'd pass to unsetopt to disable them
            // For default-ON options: show "noOPTION" (to turn it off)
            // For default-OFF options: show "OPTION" (already off, but this is what you'd type)
            let defaults_on = Self::default_on_options();
            let mut all_opts: Vec<String> = Vec::new();

            for &opt in Self::all_zsh_options() {
                let is_default_on = defaults_on.contains(&opt);
                if is_default_on {
                    all_opts.push(format!("no{}", opt));
                } else {
                    all_opts.push(opt.to_string());
                }
            }
            all_opts.sort();
            for opt in all_opts {
                println!("{}", opt);
            }
            return 0;
        }

        let mut use_pattern = false;
        let mut iter = args.iter().peekable();

        while let Some(arg) = iter.next() {
            match arg.as_str() {
                "-m" => use_pattern = true,
                "-o" => {
                    // -o option_name: unset option
                    if let Some(opt) = iter.next() {
                        let (name, enable) = Self::normalize_option_name(opt);
                        self.options.insert(name, !enable);
                    }
                }
                "+o" => {
                    // +o option_name: set option (opposite in unsetopt)
                    if let Some(opt) = iter.next() {
                        let (name, enable) = Self::normalize_option_name(opt);
                        self.options.insert(name, enable);
                    }
                }
                _ => {
                    if use_pattern {
                        for opt in Self::all_zsh_options() {
                            if Self::option_matches_pattern(opt, arg) {
                                self.options.insert(opt.to_string(), false);
                            }
                        }
                    } else {
                        let (name, enable) = Self::normalize_option_name(arg);
                        // zsh: unknown option name -> `unsetopt:1: no
                        // such option: NAME` exit 1. zshrs blindly
                        // inserted whatever name it received into
                        // self.options, leaving stale junk in the map
                        // and silencing typos.
                        if !ZSH_OPTIONS_SET.contains(name.as_str()) {
                            eprintln!("zshrs:unsetopt:1: no such option: {}", arg);
                            return 1;
                        }
                        // unsetopt turns OFF the option (or ON if "no" prefix)
                        self.options.insert(name, !enable);
                    }
                }
            }
        }
        0
    }

    fn builtin_getopts(&mut self, args: &[String]) -> i32 {
        if args.len() < 2 {
            // zsh: bare `getopts` (or with only one arg) errors
            // `getopts:1: not enough arguments` exit 1. zshrs's
            // bash-style usage banner had no shell-name prefix.
            eprintln!("zshrs:getopts:1: not enough arguments");
            return 1;
        }

        let optstring = &args[0];
        let varname = &args[1];
        let opt_args: Vec<&str> = if args.len() > 2 {
            args[2..].iter().map(|s| s.as_str()).collect()
        } else {
            self.positional_params.iter().map(|s| s.as_str()).collect()
        };

        // Get current OPTIND
        let optind: usize = self
            .variables
            .get("OPTIND")
            .and_then(|s| s.parse().ok())
            .unwrap_or(1);

        if optind > opt_args.len() {
            self.variables.insert(varname.to_string(), "?".to_string());
            return 1;
        }

        let current_arg = opt_args[optind - 1];

        if !current_arg.starts_with('-') || current_arg == "-" {
            self.variables.insert(varname.to_string(), "?".to_string());
            return 1;
        }

        if current_arg == "--" {
            self.variables
                .insert("OPTIND".to_string(), (optind + 1).to_string());
            self.variables.insert(varname.to_string(), "?".to_string());
            return 1;
        }

        // Get current option position within the argument
        let optpos: usize = self
            .variables
            .get("_OPTPOS")
            .and_then(|s| s.parse().ok())
            .unwrap_or(1);

        let opt_char = current_arg.chars().nth(optpos);

        if let Some(c) = opt_char {
            // Look up option in optstring
            let opt_idx = optstring.find(c);

            match opt_idx {
                Some(idx) => {
                    // Check if option takes an argument
                    let takes_arg = optstring.chars().nth(idx + 1) == Some(':');

                    if takes_arg {
                        // Get argument. Two shapes:
                        //   `-bX`  → arg is the rest of the same word, advance 1.
                        //   `-b X` → arg is the next word, advance 2.
                        let (arg, advance) = if optpos + 1 < current_arg.len() {
                            (current_arg[optpos + 1..].to_string(), 1usize)
                        } else if optind < opt_args.len() {
                            (opt_args[optind].to_string(), 2)
                        } else {
                            // Missing argument. Direct port of
                            // src/zsh/Src/builtin.c:5743-5763:
                            //   - quiet (`:` prefix): var=":",
                            //     OPTARG=opt_char (single-char form)
                            //   - non-quiet: var="?", OPTARG="",
                            //     warning to stderr
                            // Previous Rust always set var="?" and
                            // OPTARG=opt_char, diverging in both
                            // modes.
                            let quiet = optstring.starts_with(':');
                            // builtin.c:5747-5750 — POSIX mode also
                            // advances OPTIND past the bad option.
                            self.variables
                                .insert("OPTIND".to_string(), (optind + 1).to_string());
                            self.variables.remove("_OPTPOS");
                            if quiet {
                                self.variables.insert(varname.to_string(), ":".to_string());
                                self.variables.insert("OPTARG".to_string(), c.to_string());
                            } else {
                                self.variables.insert(varname.to_string(), "?".to_string());
                                self.variables.insert("OPTARG".to_string(), String::new());
                                eprintln!(
                                    "zshrs:getopts:1: argument expected after -{} option",
                                    c
                                );
                            }
                            return 0;
                        };

                        self.variables.insert("OPTARG".to_string(), arg);
                        self.variables
                            .insert("OPTIND".to_string(), (optind + advance).to_string());
                        self.variables.remove("_OPTPOS");
                    } else {
                        // No argument needed — clear OPTARG so the
                        // previous iteration's value doesn't leak into
                        // a subsequent flag that doesn't take one.
                        self.variables.remove("OPTARG");
                        if optpos + 1 < current_arg.len() {
                            // More options in this arg
                            self.variables
                                .insert("_OPTPOS".to_string(), (optpos + 1).to_string());
                        } else {
                            // Move to next arg
                            self.variables
                                .insert("OPTIND".to_string(), (optind + 1).to_string());
                            self.variables.remove("_OPTPOS");
                        }
                    }

                    self.variables.insert(varname.to_string(), c.to_string());
                    0
                }
                None => {
                    // Unknown option. Direct port of
                    // src/zsh/Src/builtin.c:5723-5739:
                    //   - quiet (`:` prefix): var="?",
                    //     OPTARG=opt_char (single-char form)
                    //   - non-quiet: var="?", OPTARG="", warning
                    // Always advance OPTIND in POSIX mode
                    // (builtin.c:5726-5729).
                    let quiet = optstring.starts_with(':');
                    self.variables.insert(varname.to_string(), "?".to_string());
                    if quiet {
                        self.variables.insert("OPTARG".to_string(), c.to_string());
                    } else {
                        self.variables.insert("OPTARG".to_string(), String::new());
                        eprintln!("zshrs:1: bad option: -{}", c);
                    }

                    // Advance to next option/arg
                    if optpos + 1 < current_arg.len() {
                        self.variables
                            .insert("_OPTPOS".to_string(), (optpos + 1).to_string());
                    } else {
                        self.variables
                            .insert("OPTIND".to_string(), (optind + 1).to_string());
                        self.variables.remove("_OPTPOS");
                    }
                    0
                }
            }
        } else {
            // No more options in current arg
            self.variables
                .insert("OPTIND".to_string(), (optind + 1).to_string());
            self.variables.remove("_OPTPOS");
            self.variables.insert(varname.to_string(), "?".to_string());
            1
        }
    }

    fn builtin_type(&mut self, args: &[String]) -> i32 {
        // zsh: bare `type` (no args) exits 1 — type requires at
        // least one name to look up. zshrs returned 0 silently.
        if args.is_empty() {
            return 1;
        }

        let mut show_all = false;
        let mut path_only = false;
        let mut silent = false;
        let mut show_type = false;
        let mut show_word = false;
        let mut names = Vec::new();

        let mut iter = args.iter();
        while let Some(arg) = iter.next() {
            if arg.starts_with('-') && arg.len() > 1 {
                for c in arg[1..].chars() {
                    match c {
                        '-' => {
                            // Skip `-` chars in the body (zsh quirk:
                            // for `--help` the second `-` is silently
                            // consumed and `h` becomes the first
                            // recognised letter — bad-option diag
                            // reports `-h` not `--`).
                        }
                        'a' => show_all = true,
                        'p' => path_only = true,
                        'P' => path_only = true,
                        's' => silent = true,
                        't' => show_type = true,
                        'f' => {} // ignore functions (we still show them)
                        // `-w` is `name: type` form — zsh's "word"
                        // shorthand (`builtin`/`command`/`function`/
                        // `alias`/`reserved`/`none`).
                        'w' => show_word = true,
                        // zsh's `-S` flag is silently accepted (no
                        // documented effect in `-c` mode); zshrs's
                        // unknown-flag fallback erred. zsh's `-k`
                        // (lookup as keyword/builtin only) is also
                        // silent-accept.
                        'S' | 'k' => {}
                        _ => {
                            // zsh: unknown flag → `bad option: -X`
                            // exit 1. zshrs previously dropped silently.
                            eprintln!("zshrs:type:1: bad option: -{}", c);
                            return 1;
                        }
                    }
                }
            } else {
                names.push(arg.clone());
            }
        }

        if names.is_empty() {
            return 0;
        }

        // zsh treats reserved words / keywords as a distinct type.
        // `type for` / `type while` etc. report "is a reserved word".
        // Check this BEFORE the alias/function/builtin probes so
        // user-shadowed reserved-word names still report the keyword
        // status (matches zsh's lookup order).
        const RESERVED_WORDS: &[&str] = &[
            "do",
            "done",
            "esac",
            "then",
            "elif",
            "else",
            "fi",
            "for",
            "case",
            "if",
            "while",
            "until",
            "select",
            "function",
            "repeat",
            "time",
            "in",
            "foreach",
            "end",
            "coproc",
            "nocorrect",
            "noglob",
            // zsh treats `local` / `declare` / `typeset` / `readonly`
            // / `export` / `integer` / `float` as reserved-word
            // declarations (precommand modifiers) — `type local`
            // reports "is a reserved word", not "is a shell builtin".
            "local",
            "declare",
            "typeset",
            "readonly",
            "export",
            "integer",
            "float",
        ];

        let mut status = 0;
        for name in &names {
            let mut found_any = false;

            // Reserved words win first.
            if RESERVED_WORDS.contains(&name.as_str()) {
                found_any = true;
                if !silent {
                    if show_word {
                        println!("{}: reserved", name);
                    } else if show_type {
                        println!("reserved");
                    } else {
                        println!("{} is a reserved word", name);
                    }
                }
                if !show_all {
                    continue;
                }
            }

            // Check for alias (skip if -p)
            if !path_only && self.aliases.contains_key(name) {
                found_any = true;
                if !silent {
                    if show_word {
                        println!("{}: alias", name);
                    } else if show_type {
                        println!("alias");
                    } else {
                        println!(
                            "{} is an alias for {}",
                            name,
                            self.aliases.get(name).unwrap()
                        );
                        // Note: matches zsh's `type` format, distinct
                        // from `which`'s "{}: aliased to {}" form.
                    }
                }
                if !show_all {
                    continue;
                }
            }

            // Check for function (skip if -p)
            if !path_only && self.function_exists(name) {
                found_any = true;
                if !silent {
                    if show_word {
                        println!("{}: function", name);
                    } else if show_type {
                        println!("function");
                    } else {
                        println!("{} is a shell function from zsh", name);
                    }
                }
                if !show_all {
                    continue;
                }
            }

            // Check for builtin (skip if -p). NOTE: use BUILTIN_SET
            // directly instead of `is_builtin()` — the helper has a
            // `_`-prefix bypass for completion functions, so any name
            // starting with `_` would falsely report as a builtin.
            // `type __notexist__` previously hit that bypass and
            // emitted `__notexist__ is a shell builtin` exit 0 — both
            // wrong wording AND wrong exit. Mirror the fix already
            // applied in `whence`.
            if !path_only && (BUILTIN_SET.contains(name.as_str()) || name == ":" || name == "[") {
                found_any = true;
                if !silent {
                    if show_word {
                        println!("{}: builtin", name);
                    } else if show_type {
                        println!("builtin");
                    } else {
                        println!("{} is a shell builtin", name);
                    }
                }
                if !show_all {
                    continue;
                }
            }

            // Check for external command in PATH. Skip the lookup
            // entirely for empty names — `dir + "/" + ""` resolves to
            // the directory itself, which `Path::exists` reports as
            // true, falsely matching `type ""` to the first PATH entry.
            // zsh: `type ""` -> ` not found` exit 0.
            if !name.is_empty() {
                if let Ok(path_env) = std::env::var("PATH") {
                    for dir in path_env.split(':') {
                        let full_path = format!("{}/{}", dir, name);
                        if std::path::Path::new(&full_path).exists() {
                            found_any = true;
                            if !silent {
                                if show_word {
                                    println!("{}: command", name);
                                } else if show_type {
                                    println!("file");
                                } else {
                                    println!("{} is {}", name, full_path);
                                }
                            }
                            if !show_all {
                                break;
                            }
                        }
                    }
                }
            }

            if !found_any {
                // zsh's format: `NAME not found` on stdout (no
                // colon-separated prefix). For -w, use `name: none`.
                if !silent {
                    if show_word {
                        println!("{}: none", name);
                    } else {
                        println!("{} not found", name);
                    }
                }
                status = 1;
            }
        }
        status
    }

    fn builtin_hash(&mut self, args: &[String]) -> i32 {
        // hash [ -Ldfmrv ] [ name[=value] ] ...
        // hash -r clears the hash table
        // hash -d manages named directories
        // hash -f fills the table with all PATH commands
        // hash -m matches patterns
        // hash -v verbose
        // hash -L list in form suitable for reinput

        let mut dir_mode = false;
        let mut rehash = false;
        let mut fill_all = false;
        let mut pattern_match = false;
        let mut verbose = false;
        let mut list_form = false;
        let mut names = Vec::new();

        let mut i = 0;
        while i < args.len() {
            let arg = &args[i];
            if arg.starts_with('-') && arg.len() > 1 {
                for ch in arg[1..].chars() {
                    match ch {
                        'd' => dir_mode = true,
                        'r' => rehash = true,
                        'f' => fill_all = true,
                        'm' => pattern_match = true,
                        'v' => verbose = true,
                        'L' => list_form = true,
                        // BUILTIN("hash", ..., "Ldfmrv") — exactly six
                        // valid flag letters. `hash -X foo` should
                        // error like zsh, not silently add `foo` to
                        // the hash table.
                        _ => {
                            eprintln!("zshrs:hash:1: bad option: -{}", ch);
                            return 1;
                        }
                    }
                }
            } else {
                names.push(arg.clone());
            }
            i += 1;
        }

        // builtin.c:4247-4252 — `-r` and `-f` reject positional
        // args ("too many arguments") because they're table-wide
        // operations. zshrs previously: `-r foo` silently fell
        // through to add `foo` to the hash table; `-f foo` silently
        // ignored `foo` and rebuilt the table. Both masked typos in
        // user scripts that meant `unhash` or plain `hash`.
        if (rehash || fill_all) && !names.is_empty() {
            eprintln!("zshrs:hash:1: too many arguments");
            return 1;
        }

        // -r: clear hash table
        if rehash && !dir_mode {
            self.command_hash.clear();
            return 0;
        }

        // -f: fill hash table with all commands in PATH
        if fill_all {
            if let Ok(path_var) = env::var("PATH") {
                for dir in path_var.split(':') {
                    if let Ok(entries) = std::fs::read_dir(dir) {
                        for entry in entries.flatten() {
                            if let Ok(ft) = entry.file_type() {
                                if ft.is_file() || ft.is_symlink() {
                                    if let Some(name) = entry.file_name().to_str() {
                                        let path = entry.path().to_string_lossy().to_string();
                                        self.command_hash.insert(name.to_string(), path);
                                    }
                                }
                            }
                        }
                    }
                }
            }
            return 0;
        }

        if dir_mode {
            // Named directories mode (hash -d). Sorted by name to
            // match zsh's table-walk order and stabilize the listing.
            if names.is_empty() {
                let mut sorted: Vec<(&String, &PathBuf)> =
                    self.named_dirs.iter().collect();
                sorted.sort_by(|a, b| a.0.cmp(b.0));
                for (name, path) in sorted {
                    if list_form {
                        println!("hash -d {}={}", name, path.display());
                    } else if verbose {
                        println!("{}={}", name, path.display());
                    } else {
                        println!("{}={}", name, path.display());
                    }
                }
                return 0;
            }

            if rehash {
                // Remove named directories
                if pattern_match {
                    // -m: pattern matching
                    let to_remove: Vec<String> = self
                        .named_dirs
                        .keys()
                        .filter(|k| {
                            names
                                .iter()
                                .any(|pat| Self::glob_match_static(k, pat.as_str()))
                        })
                        .cloned()
                        .collect();
                    for name in to_remove {
                        self.named_dirs.remove(&name);
                    }
                } else {
                    for name in &names {
                        self.named_dirs.remove(name);
                    }
                }
                return 0;
            }

            // Add named directories
            for name in &names {
                if let Some((n, p)) = name.split_once('=') {
                    self.add_named_dir(n, p);
                } else {
                    eprintln!("hash: -d: {} not in name=value format", name);
                    return 1;
                }
            }
            return 0;
        }

        // Regular hash - command path lookup
        if names.is_empty() {
            // List all hashed commands. zsh lists them sorted by name
            // (per builtin.c bin_hash via the table-walk on the sorted
            // hash); zshrs's HashMap iteration was nondeterministic so
            // listings flickered between runs and broke diff-based
            // tests. Sort by key.
            let mut sorted: Vec<(&String, &String)> = self.command_hash.iter().collect();
            sorted.sort_by(|a, b| a.0.cmp(b.0));
            for (name, path) in sorted {
                if list_form {
                    println!("hash {}={}", name, path);
                } else {
                    println!("{}={}", name, path);
                }
            }
            return 0;
        }

        for name in &names {
            if let Some((cmd, path)) = name.split_once('=') {
                // Explicit assignment
                self.command_hash.insert(cmd.to_string(), path.to_string());
                if verbose {
                    println!("{}={}", cmd, path);
                }
            } else if let Some(path) = self.find_in_path(name) {
                // Look up in PATH and hash it
                self.command_hash.insert(name.clone(), path.clone());
                if verbose {
                    println!("{}={}", name, path);
                }
            } else {
                eprintln!("zshrs: hash: {}: not found", name);
                return 1;
            }
        }
        0
    }

    /// add-zsh-hook builtin - add function to hook
    fn builtin_add_zsh_hook(&mut self, args: &[String]) -> i32 {
        // add-zsh-hook [-d] hook function
        if args.len() < 2 {
            eprintln!("usage: add-zsh-hook [-d] hook function");
            return 1;
        }

        let (delete, hook, func) = if args[0] == "-d" {
            if args.len() < 3 {
                eprintln!("usage: add-zsh-hook -d hook function");
                return 1;
            }
            (true, &args[1], &args[2])
        } else {
            (false, &args[0], &args[1])
        };

        if delete {
            // Remove function from hook
            if let Some(funcs) = self.hook_functions.get_mut(hook.as_str()) {
                funcs.retain(|f| f != func);
            }
        } else {
            // Add function to hook
            self.add_hook(hook, func);
        }
        0
    }

    fn builtin_command(&mut self, args: &[String], redirects: &[Redirect]) -> i32 {
        // command [ -pvV ] simple command
        // -p: use default PATH
        // -v: print path (like which)
        // -V: verbose description (like type)
        let mut use_default_path = false;
        let mut print_path = false;
        let mut verbose = false;
        let mut positional_args: Vec<&str> = Vec::new();

        let mut i = 0;
        while i < args.len() {
            let arg = &args[i];
            if arg == "--" {
                // Bare `--` ends options; rest are positional.
                i += 1;
                while i < args.len() {
                    positional_args.push(&args[i]);
                    i += 1;
                }
                break;
            }
            if arg.starts_with('-') && arg.len() > 1 && positional_args.is_empty() {
                // `command --foo` (long-option-style) — zsh treats the
                // whole thing as a command NAME to invoke (no built-in
                // long-option support). Mirror by emitting the
                // command-not-found diagnostic for any `--xxx` form.
                if arg.starts_with("--") {
                    eprintln!("zshrs:1: command not found: {}", arg);
                    return 127;
                }
                for ch in arg[1..].chars() {
                    match ch {
                        'p' => use_default_path = true,
                        'v' => print_path = true,
                        'V' => verbose = true,
                        _ => {
                            // zsh treats an unknown -X as a command
                            // name to invoke, not as a flag error.
                            // `command -x ls` → "command not found: -x"
                            // (and the rest of args become args to that
                            // bogus command). Match by emitting the
                            // command-not-found diagnostic instead of
                            // the flag-error message.
                            eprintln!("zshrs:1: command not found: -{}", ch);
                            return 127;
                        }
                    }
                }
            } else {
                positional_args.push(arg);
            }
            i += 1;
        }

        // Add remaining args after --
        while i < args.len() {
            positional_args.push(&args[i]);
            i += 1;
        }

        if positional_args.is_empty() {
            // zsh: bare `command` with no args AND no redirections
            // exits 0 silently. The "redirection with no command"
            // error in zsh fires only when redirections were present
            // (e.g. `command >file`) — that case is handled by the
            // parser, not here. The builtin sees identical empty-args
            // for both cases, so we mirror the bare-command exit 0
            // (matches bash too).
            return 0;
        }

        let cmd = positional_args[0];

        // -v or -V: print info about command. Resolution order matches
        // zsh's `whence`: alias → function → builtin → reserved word →
        // external. -v prints just the resolved name (or path for an
        // external); -V is the verbose human-readable form.
        if print_path || verbose {
            // Alias
            if let Some(target) = self.aliases.get(cmd) {
                if verbose {
                    println!("{} is an alias for {}", cmd, target);
                } else {
                    println!("alias {}={}", cmd, shell_quote_value(target));
                }
                return 0;
            }
            // Function
            if self.function_exists(cmd) {
                if verbose {
                    // zsh prints "is a shell function from <source>";
                    // for built-from-script defns the source is "zsh".
                    println!("{} is a shell function from zsh", cmd);
                } else {
                    println!("{}", cmd);
                }
                return 0;
            }
            // Shell builtin
            if self.is_builtin(cmd) || cmd == ":" || cmd == "[" {
                if verbose {
                    println!("{} is a shell builtin", cmd);
                } else {
                    println!("{}", cmd);
                }
                return 0;
            }
            // Reserved word (if/then/else/etc.)
            let reserved = matches!(
                cmd,
                "if" | "then"
                    | "else"
                    | "elif"
                    | "fi"
                    | "for"
                    | "while"
                    | "until"
                    | "do"
                    | "done"
                    | "case"
                    | "esac"
                    | "in"
                    | "function"
                    | "select"
                    | "time"
                    | "coproc"
                    | "{"
                    | "}"
                    | "[["
                    | "]]"
            );
            if reserved {
                if verbose {
                    println!("{} is a reserved word", cmd);
                } else {
                    println!("{}", cmd);
                }
                return 0;
            }
            // External
            let path_var = if use_default_path {
                "/usr/local/bin:/usr/bin:/bin:/usr/sbin:/sbin".to_string()
            } else {
                env::var("PATH").unwrap_or_default()
            };

            for dir in path_var.split(':') {
                let full_path = PathBuf::from(dir).join(cmd);
                if full_path.exists() && full_path.is_file() {
                    if verbose {
                        println!("{} is {}", cmd, full_path.display());
                    } else {
                        println!("{}", full_path.display());
                    }
                    return 0;
                }
            }

            if verbose {
                eprintln!("{} not found", cmd);
            }
            return 1;
        }

        // Execute as external command (bypassing functions and aliases)
        let cmd_args: Vec<String> = positional_args[1..].iter().map(|s| s.to_string()).collect();

        if use_default_path {
            // Temporarily set PATH
            let old_path = env::var("PATH").ok();
            env::set_var("PATH", "/usr/local/bin:/usr/bin:/bin:/usr/sbin:/sbin");
            let result = self
                .execute_external(
                    cmd,
                    &cmd_args
                        .iter()
                        .map(|s| s.as_str())
                        .collect::<Vec<_>>()
                        .join(" ")
                        .split_whitespace()
                        .map(String::from)
                        .collect::<Vec<_>>(),
                    redirects,
                )
                .unwrap_or(127);
            if let Some(p) = old_path {
                env::set_var("PATH", p);
            }
            result
        } else {
            self.execute_external(cmd, &cmd_args, redirects)
                .unwrap_or(127)
        }
    }

    fn builtin_builtin(&mut self, args: &[String], redirects: &[Redirect]) -> i32 {
        // Run builtin, bypassing functions and aliases
        if args.is_empty() {
            return 0;
        }

        let cmd = &args[0];
        let cmd_args = &args[1..];

        match cmd.as_str() {
            "cd" => self.builtin_cd(cmd_args),
            "pwd" => self.builtin_pwd(redirects),
            "echo" => self.builtin_echo(cmd_args, redirects),
            "export" => self.builtin_export(cmd_args),
            "unset" => self.builtin_unset(cmd_args),
            "exit" => self.builtin_exit(cmd_args),
            "return" => self.builtin_return(cmd_args),
            "logout" => {
                // zsh: `logout` is the login-shell-only counterpart to
                // `exit`. Outside a login shell it fails with "not
                // login shell" (with `(anon):logout:` or
                // `<funcname>:logout:` prefix in a function context,
                // `zsh:logout:1:` at top level). Detect via the LOGIN
                // option (set when invoked as `-l` or via `--login`).
                if self.options.get("login").copied().unwrap_or(false) {
                    self.builtin_exit(cmd_args)
                } else {
                    let prefix = if self.local_scope_depth > 0 {
                        let name = self
                            .arrays
                            .get("funcstack")
                            .and_then(|s| s.first().cloned())
                            .unwrap_or_else(|| "anon".to_string());
                        format!("({}):logout", name)
                    } else {
                        "zshrs:logout:1".to_string()
                    };
                    eprintln!("{}: not login shell", prefix);
                    1
                }
            }
            "true" => 0,
            "false" => 1,
            ":" => 0,
            "test" | "[" => self.builtin_test(cmd_args),
            "local" => self.builtin_local(cmd_args),
            "private" => self.builtin_local(cmd_args),
            "declare" => self.builtin_declare(cmd_args),
            "typeset" => self.builtin_typeset(cmd_args),
            "read" => self.builtin_read(cmd_args),
            "shift" => self.builtin_shift(cmd_args),
            "eval" => self.builtin_eval(cmd_args),
            "alias" => self.builtin_alias(cmd_args),
            "unalias" => self.builtin_unalias(cmd_args),
            "set" => self.builtin_set(cmd_args),
            "getopts" => self.builtin_getopts(cmd_args),
            "type" => self.builtin_type(cmd_args),
            "hash" => self.builtin_hash(cmd_args),
            "add-zsh-hook" => self.builtin_add_zsh_hook(cmd_args),
            "autoload" => self.builtin_autoload(cmd_args),
            "source" => self.builtin_source_named(cmd_args, "source"),
            "." => self.builtin_source_named(cmd_args, "."),
            "functions" => self.builtin_functions(cmd_args),
            "zle" => self.builtin_zle(cmd_args),
            "bindkey" => self.builtin_bindkey(cmd_args),
            "setopt" => self.builtin_setopt(cmd_args),
            "unsetopt" => self.builtin_unsetopt(cmd_args),
            "emulate" => self.builtin_emulate(cmd_args),
            "zstyle" => self.builtin_zstyle(cmd_args),
            "compadd" => self.builtin_compadd(cmd_args),
            "compset" => self.builtin_compset(cmd_args),
            "compdef" => self.builtin_compdef(cmd_args),
            "compinit" => self.builtin_compinit(cmd_args),
            "cdreplay" => self.builtin_cdreplay(cmd_args),
            "zmodload" => self.builtin_zmodload(cmd_args),
            "zcompile" => self.builtin_zcompile(cmd_args),
            "zformat" => self.builtin_zformat(cmd_args),
            "zprof" => self.builtin_zprof(cmd_args),
            "print" => self.builtin_print(cmd_args),
            "printf" => self.builtin_printf(cmd_args),
            "command" => self.builtin_command(cmd_args, redirects),
            "whence" => self.builtin_whence(cmd_args),
            "which" => self.builtin_which(cmd_args),
            "where" => self.builtin_where(cmd_args),
            "fc" => self.builtin_fc(cmd_args),
            "history" => self.builtin_history(cmd_args),
            "dirs" => self.builtin_dirs(cmd_args),
            "pushd" => self.builtin_pushd(cmd_args),
            "popd" => self.builtin_popd(cmd_args),
            "bg" => self.builtin_bg(cmd_args),
            "fg" => self.builtin_fg(cmd_args),
            "jobs" => self.builtin_jobs(cmd_args),
            "kill" => self.builtin_kill(cmd_args),
            "wait" => self.builtin_wait(cmd_args),
            "trap" => self.builtin_trap(cmd_args),
            "umask" => self.builtin_umask(cmd_args),
            "ulimit" => self.builtin_ulimit(cmd_args),
            "times" => self.builtin_times(cmd_args),
            "let" => self.builtin_let(cmd_args),
            "integer" => self.builtin_integer(cmd_args),
            "float" => self.builtin_float(cmd_args),
            "readonly" => self.builtin_readonly(cmd_args),
            // zsh-bundled rename helpers — natively implemented so
            // `autoload -U zmv` doesn't actually need to load the
            // zsh function source file. See builtin_zmv for semantics.
            "zmv" => self.builtin_zmv(cmd_args, "mv"),
            "zcp" => self.builtin_zmv(cmd_args, "cp"),
            "zln" => self.builtin_zmv(cmd_args, "ln"),
            "zcalc" => self.builtin_zcalc(cmd_args),
            // Daemon-managed z* builtins — thin IPC wrappers. Name list is
            // owned by the daemon crate; routing via try_dispatch keeps this
            // site zero-touch as new z* builtins land.
            n if crate::daemon::builtins::is_zshrs_builtin(n) => {
                let argv: Vec<String> = std::iter::once(cmd.to_string())
                    .chain(cmd_args.iter().cloned())
                    .collect();
                crate::daemon::builtins::try_dispatch(n, &argv).unwrap_or(1)
            }
            _ => {
                eprintln!("zshrs:1: no such builtin: {}", cmd);
                1
            }
        }
    }

    fn builtin_let(&mut self, args: &[String]) -> i32 {
        // Direct port of src/zsh/Src/builtin.c:7469-7482 bin_let.
        //
        // Algorithm:
        //   val = zero_mnumber       // 0 (integer)
        //   for each arg: val = matheval(arg)  // evaluate, last
        //                                       // wins
        //   if errflag: return 2     // math errors non-fatal
        //   return val == 0 ? 1 : 0  // 1 = false, 0 = true
        //
        // No arg case: val stays 0, returns 1 (false). zsh does NOT
        // emit a "not enough arguments" diagnostic for bare `let` —
        // zshrs's previous impl invented one. POSIX/zsh treat the
        // empty case as a valid no-op-with-status-1.
        let mut result: i64 = 0;
        for expr in args {
            result = self.evaluate_arithmetic_expr(expr);
        }
        if result == 0 {
            1
        } else {
            0
        }
    }

    /// Generate completion candidates
    fn builtin_compgen(&self, args: &[String]) -> i32 {
        let mut i = 0;
        let mut prefix = String::new();
        let mut actions = Vec::new();
        let mut wordlist = None;
        let mut globpat = None;

        while i < args.len() {
            match args[i].as_str() {
                "-W" => {
                    i += 1;
                    if i < args.len() {
                        wordlist = Some(args[i].clone());
                    }
                }
                "-G" => {
                    i += 1;
                    if i < args.len() {
                        globpat = Some(args[i].clone());
                    }
                }
                "-a" => actions.push("alias"),
                "-b" => actions.push("builtin"),
                "-c" => actions.push("command"),
                "-d" => actions.push("directory"),
                "-e" => actions.push("export"),
                "-f" => actions.push("file"),
                "-j" => actions.push("job"),
                "-k" => actions.push("keyword"),
                "-u" => actions.push("user"),
                "-v" => actions.push("variable"),
                s if !s.starts_with('-') => prefix = s.to_string(),
                _ => {}
            }
            i += 1;
        }

        let mut results = Vec::new();

        // Generate based on actions
        for action in actions {
            match action {
                "alias" => {
                    let mut names: Vec<String> = self.aliases.keys().cloned().collect();
                    names.sort();
                    for name in names {
                        if name.starts_with(&prefix) {
                            results.push(name);
                        }
                    }
                }
                "builtin" => {
                    // Use the canonical BUILTIN_SET so every wired
                    // builtin shows up in completion (was a hardcoded
                    // 25-entry subset that missed bindkey, fc, getopts,
                    // shopt, typeset, etc).
                    let mut names: Vec<&str> = BUILTIN_SET.iter().copied().collect();
                    names.sort();
                    for name in names {
                        if name.starts_with(&prefix) {
                            results.push(name.to_string());
                        }
                    }
                }
                "directory" => {
                    // Sort dir entries for stable completion order.
                    if let Ok(entries) = std::fs::read_dir(".") {
                        let mut names: Vec<String> = entries
                            .flatten()
                            .filter(|e| {
                                e.file_type().map(|ft| ft.is_dir()).unwrap_or(false)
                            })
                            .map(|e| e.file_name().to_string_lossy().into_owned())
                            .collect();
                        names.sort();
                        for name in names {
                            if name.starts_with(&prefix) {
                                results.push(name);
                            }
                        }
                    }
                }
                "file" => {
                    if let Ok(entries) = std::fs::read_dir(".") {
                        let mut names: Vec<String> = entries
                            .flatten()
                            .map(|e| e.file_name().to_string_lossy().into_owned())
                            .collect();
                        names.sort();
                        for name in names {
                            if name.starts_with(&prefix) {
                                results.push(name);
                            }
                        }
                    }
                }
                "variable" => {
                    // Sort for deterministic completion-candidate
                    // order (was HashMap iteration random, so
                    // \`compgen -v\` listings flickered).
                    let mut names: Vec<String> = self.variables.keys().cloned().collect();
                    names.sort();
                    for name in names {
                        if name.starts_with(&prefix) {
                            results.push(name);
                        }
                    }
                    let mut env_names: Vec<String> =
                        std::env::vars().map(|(k, _)| k).collect();
                    env_names.sort();
                    for name in env_names {
                        if name.starts_with(&prefix) && !results.contains(&name) {
                            results.push(name);
                        }
                    }
                }
                _ => {}
            }
        }

        // Handle wordlist
        if let Some(words) = wordlist {
            for word in words.split_whitespace() {
                if word.starts_with(&prefix) {
                    results.push(word.to_string());
                }
            }
        }

        // Handle glob pattern
        if let Some(_pattern) = globpat {
            let full_pattern = format!("{}*", prefix);
            if let Ok(paths) = glob::glob(&full_pattern) {
                for path in paths.flatten() {
                    results.push(path.to_string_lossy().to_string());
                }
            }
        }

        results.sort();
        results.dedup();
        for r in results {
            println!("{}", r);
        }
        0
    }

    /// Define completion spec for a command
    fn builtin_complete(&mut self, args: &[String]) -> i32 {
        if args.is_empty() {
            // List all completion specs, sorted by command name so
            // 'complete' (no args) outputs deterministically.
            let mut cmds: Vec<&String> = self.completions.keys().collect();
            cmds.sort();
            for cmd in cmds {
                let spec = self.completions.get(cmd).unwrap();
                let mut parts = vec!["complete".to_string()];
                for action in &spec.actions {
                    parts.push(format!("-{}", action));
                }
                if let Some(ref w) = spec.wordlist {
                    parts.push("-W".to_string());
                    parts.push(format!("'{}'", w));
                }
                if let Some(ref f) = spec.function {
                    parts.push("-F".to_string());
                    parts.push(f.clone());
                }
                if let Some(ref c) = spec.command {
                    parts.push("-C".to_string());
                    parts.push(c.clone());
                }
                parts.push(cmd.clone());
                println!("{}", parts.join(" "));
            }
            return 0;
        }

        let mut spec = CompSpec::default();
        let mut commands = Vec::new();
        let mut i = 0;

        while i < args.len() {
            match args[i].as_str() {
                "-W" => {
                    i += 1;
                    if i < args.len() {
                        spec.wordlist = Some(args[i].clone());
                    }
                }
                "-F" => {
                    i += 1;
                    if i < args.len() {
                        spec.function = Some(args[i].clone());
                    }
                }
                "-C" => {
                    i += 1;
                    if i < args.len() {
                        spec.command = Some(args[i].clone());
                    }
                }
                "-G" => {
                    i += 1;
                    if i < args.len() {
                        spec.globpat = Some(args[i].clone());
                    }
                }
                "-P" => {
                    i += 1;
                    if i < args.len() {
                        spec.prefix = Some(args[i].clone());
                    }
                }
                "-S" => {
                    i += 1;
                    if i < args.len() {
                        spec.suffix = Some(args[i].clone());
                    }
                }
                "-a" => spec.actions.push("a".to_string()),
                "-b" => spec.actions.push("b".to_string()),
                "-c" => spec.actions.push("c".to_string()),
                "-d" => spec.actions.push("d".to_string()),
                "-e" => spec.actions.push("e".to_string()),
                "-f" => spec.actions.push("f".to_string()),
                "-j" => spec.actions.push("j".to_string()),
                "-r" => {
                    // Remove completion spec
                    i += 1;
                    while i < args.len() {
                        self.completions.remove(&args[i]);
                        i += 1;
                    }
                    return 0;
                }
                s if !s.starts_with('-') => commands.push(s.to_string()),
                _ => {}
            }
            i += 1;
        }

        for cmd in commands {
            self.completions.insert(cmd, spec.clone());
        }
        0
    }

